#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    // W (d,n) @ x (n,) -> xout (d,)
    // Process 4 rows at a time so each chunk of x loaded once is reused 4x.
    // NEON: 4 independent FMA accumulators per row.
    int i = 0;

    for (; i + 4 <= d; i += 4) {
        const float* w0 = w + (size_t)i * n;
        const float* w1 = w0 + n;
        const float* w2 = w1 + n;
        const float* w3 = w2 + n;

        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j), xv);
            a1 = vfmaq_f32(a1, vld1q_f32(w1 + j), xv);
            a2 = vfmaq_f32(a2, vld1q_f32(w2 + j), xv);
            a3 = vfmaq_f32(a3, vld1q_f32(w3 + j), xv);
        }
        float s0 = vaddvq_f32(a0);
        float s1 = vaddvq_f32(a1);
        float s2 = vaddvq_f32(a2);
        float s3 = vaddvq_f32(a3);
        for (; j < n; j++) {
            float xj = x[j];
            s0 += w0[j] * xj;
            s1 += w1[j] * xj;
            s2 += w2[j] * xj;
            s3 += w3[j] * xj;
        }
        xout[i]     = s0;
        xout[i + 1] = s1;
        xout[i + 2] = s2;
        xout[i + 3] = s3;
    }

    for (; i < d; i++) {
        const float* wi = w + (size_t)i * n;
        float32x4_t acc = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j + 4 <= n; j += 4) {
            acc = vfmaq_f32(acc, vld1q_f32(wi + j), vld1q_f32(x + j));
        }
        float s = vaddvq_f32(acc);
        for (; j < n; j++) s += wi[j] * x[j];
        xout[i] = s;
    }
}

