typedef struct {
    float* xout;
    const float* x;
    const float* w;
    int n;
} mm_args;

static inline float dot_neon(const float* restrict w, const float* restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 16 <= n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    for (; j + 4 <= n; j += 4) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j), vld1q_f32(x + j));
    }
    float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    float sum = vaddvq_f32(s);
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

static void mm_row(void* ctx, size_t i) {
    mm_args* a = (mm_args*)ctx;
    const float* wrow = a->w + (size_t)i * (size_t)a->n;
    a->xout[i] = dot_neon(wrow, a->x, a->n);
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    mm_args args = { xout, x, w, n };
    dispatch_apply_f((size_t)d, DISPATCH_APPLY_AUTO, &args, mm_row);
}

#include <arm_neon.h>
#include <dispatch/dispatch.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    float* xout;
    const float* x;
    const float* w;
    int n;
    int i0;
    int i1;
} mm_arg_t;

static void mm_rows(void* ctx, size_t idx) {
    (void)idx;
    mm_arg_t* a = (mm_arg_t*)ctx;
    const int n = a->n;
    const float* x = a->x;
    for (int i = a->i0; i < a->i1; i++) {
        const float* wp = a->w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j + 16 <= n; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vgetq_lane_f32(s, 0) + vgetq_lane_f32(s, 1)
                  + vgetq_lane_f32(s, 2) + vgetq_lane_f32(s, 3);
        for (; j < n; j++) val += wp[j] * x[j];
        a->xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    // Split rows into ~4x-num-cores chunks; use concurrent dispatch for parallel rows.
    int ncores = 12;
    int nchunks = ncores * 4;
    if (nchunks > d) nchunks = d;
    if (nchunks < 1) nchunks = 1;
    int per = (d + nchunks - 1) / nchunks;

    mm_arg_t args[64]; // bounded by nchunks (<=48)
    dispatch_queue_t q = dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0);
    dispatch_group_t g = dispatch_group_create();
    int nch = 0;
    for (int c = 0; c < nchunks; c++) {
        int i0 = c * per;
        int i1 = i0 + per;
        if (i0 >= d) break;
        if (i1 > d) i1 = d;
        args[nch].xout = xout;
        args[nch].x = x;
        args[nch].w = w;
        args[nch].n = n;
        args[nch].i0 = i0;
        args[nch].i1 = i1;
        mm_arg_t* ap = &args[nch];
        dispatch_group_async_f(g, q, ap, mm_rows);
        nch++;
    }
    dispatch_group_wait(g, DISPATCH_TIME_FOREVER);
    dispatch_release(g);
}

