/* 4 rows in parallel: each x chunk is loaded once and reused by all rows. */
static inline void dot4_neon(const float* __restrict wa,
                             const float* __restrict wb,
                             const float* __restrict wc,
                             const float* __restrict wd,
                             const float* __restrict x, int n,
                             float* __restrict out) {
    float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
    float32x4_t b0 = vdupq_n_f32(0.0f), b1 = vdupq_n_f32(0.0f);
    float32x4_t b2 = vdupq_n_f32(0.0f), b3 = vdupq_n_f32(0.0f);
    float32x4_t c0 = vdupq_n_f32(0.0f), c1 = vdupq_n_f32(0.0f);
    float32x4_t c2 = vdupq_n_f32(0.0f), c3 = vdupq_n_f32(0.0f);
    float32x4_t e0 = vdupq_n_f32(0.0f), e1 = vdupq_n_f32(0.0f);
    float32x4_t e2 = vdupq_n_f32(0.0f), e3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        float32x4_t x0 = vld1q_f32(x + j);
        float32x4_t x1 = vld1q_f32(x + j + 4);
        float32x4_t x2 = vld1q_f32(x + j + 8);
        float32x4_t x3 = vld1q_f32(x + j + 12);

        a0 = vfmaq_f32(a0, vld1q_f32(wa + j),      x0);
        a1 = vfmaq_f32(a1, vld1q_f32(wa + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(wa + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(wa + j + 12), x3);

        b0 = vfmaq_f32(b0, vld1q_f32(wb + j),      x0);
        b1 = vfmaq_f32(b1, vld1q_f32(wb + j + 4),  x1);
        b2 = vfmaq_f32(b2, vld1q_f32(wb + j + 8),  x2);
        b3 = vfmaq_f32(b3, vld1q_f32(wb + j + 12), x3);

        c0 = vfmaq_f32(c0, vld1q_f32(wc + j),      x0);
        c1 = vfmaq_f32(c1, vld1q_f32(wc + j + 4),  x1);
        c2 = vfmaq_f32(c2, vld1q_f32(wc + j + 8),  x2);
        c3 = vfmaq_f32(c3, vld1q_f32(wc + j + 12), x3);

        e0 = vfmaq_f32(e0, vld1q_f32(wd + j),      x0);
        e1 = vfmaq_f32(e1, vld1q_f32(wd + j + 4),  x1);
        e2 = vfmaq_f32(e2, vld1q_f32(wd + j + 8),  x2);
        e3 = vfmaq_f32(e3, vld1q_f32(wd + j + 12), x3);
    }
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a0 = vaddq_f32(a0, a2);
    b0 = vaddq_f32(b0, b1);
    b2 = vaddq_f32(b2, b3);
    b0 = vaddq_f32(b0, b2);
    c0 = vaddq_f32(c0, c1);
    c2 = vaddq_f32(c2, c3);
    c0 = vaddq_f32(c0, c2);
    e0 = vaddq_f32(e0, e1);
    e2 = vaddq_f32(e2, e3);
    e0 = vaddq_f32(e0, e2);

    float sa = vaddvq_f32(a0);
    float sb = vaddvq_f32(b0);
    float sc = vaddvq_f32(c0);
    float se = vaddvq_f32(e0);
    for (; j < n; j++) {
        float xv = x[j];
        sa += wa[j] * xv;
        sb += wb[j] * xv;
        sc += wc[j] * xv;
        se += wd[j] * xv;
    }
    out[0] = sa;
    out[1] = sb;
    out[2] = sc;
    out[3] = se;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }
    /* Split rows into ~2 chunks per core so GCD can load-balance. */
    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            for (; i + 3 < end; i += 4) {
                const float* wr = w + (size_t)i * n;
                dot4_neon(wr,
                          wr + (size_t)n,
                          wr + 2 * (size_t)n,
                          wr + 3 * (size_t)n,
                          x, n, xout + i);
            }
            for (; i < end; i++) {
                xout[i] = dot_neon(w + (size_t)i * n, x, n);
            }
        });
}

