/* Process a block of rows sharing the same x, keeping x hot in L1. */
static inline void rows_block(float* __restrict xout,
                              const float* __restrict x,
                              const float* __restrict w,
                              int n, int start, int end) {
    for (int i = start; i < end; i++) {
        xout[i] = dot_neon(w + (size_t)i * n, x, n);
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 64) {
        rows_block(xout, x, w, n, 0, d);
        return;
    }
    /* More chunks for better load balancing on 12-core M3 Pro. */
    const int TARGET_CHUNKS = 36;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    /* round chunk to multiple of 4 rows for alignment of work */
    chunk = (chunk + 3) & ~3;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            if (start < end)
                rows_block(xout, x, w, n, start, end);
        });
}

