/* Compute RB rows starting at row0, reusing x in registers.
   x is loaded once per j-block and reused across RB rows. */
static inline void dot_rows(const float* __restrict w, const float* __restrict x,
                            float* __restrict out, int n, int RB) {
    for (int r = 0; r < RB; r++) {
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);
        const float* wp = w + (size_t)r * n;
        int j = 0;
        for (; j + 15 < n; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        a0 = vaddq_f32(a0, a1);
        a2 = vaddq_f32(a2, a3);
        a0 = vaddq_f32(a0, a2);
        float sum = vaddvq_f32(a0);
        for (; j < n; j++) sum += wp[j] * x[j];
        out[r] = sum;
    }
}

/* Process RB rows in parallel over j-blocks: each row reduced independently,
   but x chunk loaded once and shared across all RB rows in the block. */
static inline void dot_rows_shared(const float* __restrict w, const float* __restrict x,
                                   float* __restrict out, int n, int RB) {
    const int B = 16;
    int nblk = n / B;               /* number of full 16-wide blocks */
    int rem = n - nblk * B;

    /* accumulators: RB rows x 4 vectors */
    float32x4_t acc[8][4];
    for (int r = 0; r < RB; r++) {
        acc[r][0] = vdupq_n_f32(0.0f);
        acc[r][1] = vdupq_n_f32(0.0f);
        acc[r][2] = vdupq_n_f32(0.0f);
        acc[r][3] = vdupq_n_f32(0.0f);
    }

    for (int b = 0; b < nblk; b++) {
        const float* xb = x + b * B;
        float32x4_t x0 = vld1q_f32(xb);
        float32x4_t x1 = vld1q_f32(xb + 4);
        float32x4_t x2 = vld1q_f32(xb + 8);
        float32x4_t x3 = vld1q_f32(xb + 12);
        for (int r = 0; r < RB; r++) {
            const float* wp = w + (size_t)r * n + b * B;
            acc[r][0] = vfmaq_f32(acc[r][0], vld1q_f32(wp),      x0);
            acc[r][1] = vfmaq_f32(acc[r][1], vld1q_f32(wp + 4),  x1);
            acc[r][2] = vfmaq_f32(acc[r][2], vld1q_f32(wp + 8),  x2);
            acc[r][3] = vfmaq_f32(acc[r][3], vld1q_f32(wp + 12), x3);
        }
    }

    for (int r = 0; r < RB; r++) {
        float32x4_t a0 = vaddq_f32(acc[r][0], acc[r][1]);
        float32x4_t a2 = vaddq_f32(acc[r][2], acc[r][3]);
        a0 = vaddq_f32(a0, a2);
        float sum = vaddvq_f32(a0);
        const float* wp = w + (size_t)r * n + nblk * B;
        const float* xp = x + nblk * B;
        for (int t = 0; t < rem; t++) sum += wp[t] * xp[t];
        out[r] = sum;
    }
}

static inline void matmul_block(int start, int end, float* __restrict xout,
                                const float* __restrict x, const float* __restrict w,
                                int n, int d) {
    /* Register-blocked: RB rows at a time, x reused across rows. */
    const int RB = 4;
    int i = start;
    for (; i + RB <= end; i += RB) {
        dot_rows_shared(w + (size_t)i * n, x, xout + i, n, RB);
    }
    for (; i < end; i++) {
        dot_rows(w + (size_t)i * n, x, xout + i, n, 1);
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 64) {
        matmul_block(0, d, xout, x, w, n, d);
        return;
    }
    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    /* round chunk to multiple of 4 rows so RB blocking fits cleanly */
    chunk = (chunk + 3) & ~3;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            matmul_block(start, end, xout, x, w, n, d);
        });
}

