        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    for (; j + 3 < n; j += 4)
        a0 = vfmaq_f32(a0, vld1q_f32(w + j), vld1q_f32(x + j));
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a0 = vaddq_f32(a0, a2);
    float sum = vaddvq_f32(a0);
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

/* Process a block of rows; keep x hot in registers/L1 across rows. */
static inline void matmul_rows(float* __restrict xout,
                               const float* __restrict x,
                               const float* __restrict w,
                               int n, int start, int end) {
    for (int i = start; i < end; i++) {
        xout[i] = dot_neon(w + (size_t)i * n, x, n);
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 96) {
        matmul_rows(xout, x, w, n, 0, d);
        return;
    }
    /* Two chunks per core for load balance on 12 cores. */
    int nchunk = 24;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply_f(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        (void*)(uintptr_t)(((uintptr_t)n << 32) ^ (uintptr_t)chunk),
        ^(void* ctx, size_t t) {
            uintptr_t v = (uintptr_t)ctx;
            int n_ = (int)(v >> 32);
            int chunk_ = (int)(v & 0xffffffffu);
            int start = (int)t * chunk_;
            int end = start + chunk_;
            if (end > d) end = d;
            matmul_rows(xout, x, w, n_, start, end);
        });
}

