/* 8-accumulator NEON FMA dot product: breaks the FP dependency chain
   more aggressively than 4 accumulators, letting the M3 Pro issue
   more FMAs per cycle. Summation order: pairwise tree reduce. */
static inline float dot_neon(const float* __restrict w,
                             const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    float32x4_t a4 = vdupq_n_f32(0.0f);
    float32x4_t a5 = vdupq_n_f32(0.0f);
    float32x4_t a6 = vdupq_n_f32(0.0f);
    float32x4_t a7 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 31 < n; j += 32) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
        a4 = vfmaq_f32(a4, vld1q_f32(w + j + 16), vld1q_f32(x + j + 16));
        a5 = vfmaq_f32(a5, vld1q_f32(w + j + 20), vld1q_f32(x + j + 20));
        a6 = vfmaq_f32(a6, vld1q_f32(w + j + 24), vld1q_f32(x + j + 24));
        a7 = vfmaq_f32(a7, vld1q_f32(w + j + 28), vld1q_f32(x + j + 28));
    }
    for (; j + 15 < n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    for (; j + 3 < n; j += 4) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j), vld1q_f32(x + j));
    }
    /* pairwise reduce */
    float32x4_t s0 = vaddq_f32(a0, a1);
    float32x4_t s1 = vaddq_f32(a2, a3);
    float32x4_t s2 = vaddq_f32(a4, a5);
    float32x4_t s3 = vaddq_f32(a6, a7);
    float32x4_t t0 = vaddq_f32(s0, s1);
    float32x4_t t1 = vaddq_f32(s2, s3);
    float sum = vaddvq_f32(vaddq_f32(t0, t1));
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }
    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            for (int i = start; i < end; i++) {
                xout[i] = dot_neon(w + (size_t)i * n, x, n);
            }
        });
}

