/* 4-accumulator NEON FMA dot product for one row. */
static inline float dot_neon(const float* __restrict w,
                             const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a0 = vaddq_f32(a0, a2);
    float sum = vaddvq_f32(a0);
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

/*
 * Compute 4 rows at once. Each x chunk is loaded once into a register and
 * shared across 4 rows of w, cutting x-load traffic by 4x and giving the
 * FP unit 4 independent FMA chains to hide latency.
 */
static inline void dot4_neon(const float* __restrict w, size_t stride,
                             const float* __restrict x, int n,
                             float* __restrict out) {
    float32x4_t a0 = vdupq_n_f32(0.f), a1 = vdupq_n_f32(0.f);
    float32x4_t a2 = vdupq_n_f32(0.f), a3 = vdupq_n_f32(0.f);
    float32x4_t b0 = vdupq_n_f32(0.f), b1 = vdupq_n_f32(0.f);
    float32x4_t b2 = vdupq_n_f32(0.f), b3 = vdupq_n_f32(0.f);
    float32x4_t c0 = vdupq_n_f32(0.f), c1 = vdupq_n_f32(0.f);
    float32x4_t c2 = vdupq_n_f32(0.f), c3 = vdupq_n_f32(0.f);
    float32x4_t d0 = vdupq_n_f32(0.f), d1 = vdupq_n_f32(0.f);
    float32x4_t d2 = vdupq_n_f32(0.f), d3 = vdupq_n_f32(0.f);

    const float* __restrict w0 = w;
    const float* __restrict w1 = w + stride;
    const float* __restrict w2 = w + 2 * stride;
    const float* __restrict w3 = w + 3 * stride;

    int j = 0;
    for (; j + 15 < n; j += 16) {
        float32x4_t x0 = vld1q_f32(x + j);
        float32x4_t x1 = vld1q_f32(x + j + 4);
        float32x4_t x2 = vld1q_f32(x + j + 8);
        float32x4_t x3 = vld1q_f32(x + j + 12);

        a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
        a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(w0 + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(w0 + j + 12), x3);

        b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),      x0);
        b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4),  x1);
        b2 = vfmaq_f32(b2, vld1q_f32(w1 + j + 8),  x2);
        b3 = vfmaq_f32(b3, vld1q_f32(w1 + j + 12), x3);

        c0 = vfmaq_f32(c0, vld1q_f32(w2 + j),      x0);
        c1 = vfmaq_f32(c1, vld1q_f32(w2 + j + 4),  x1);
        c2 = vfmaq_f32(c2, vld1q_f32(w2 + j + 8),  x2);
        c3 = vfmaq_f32(c3, vld1q_f32(w2 + j + 12), x3);

        d0 = vfmaq_f32(d0, vld1q_f32(w3 + j),      x0);
        d1 = vfmaq_f32(d1, vld1q_f32(w3 + j + 4),  x1);
        d2 = vfmaq_f32(d2, vld1q_f32(w3 + j + 8),  x2);
        d3 = vfmaq_f32(d3, vld1q_f32(w3 + j + 12), x3);
    }

    a0 = vaddq_f32(a0, a1); a2 = vaddq_f32(a2, a3); a0 = vaddq_f32(a0, a2);
    b0 = vaddq_f32(b0, b1); b2 = vaddq_f32(b2, b3); b0 = vaddq_f32(b0, b2);
    c0 = vaddq_f32(c0, c1); c2 = vaddq_f32(c2, c3); c0 = vaddq_f32(c0, c2);
    d0 = vaddq_f32(d0, d1); d2 = vaddq_f32(d2, d3); d0 = vaddq_f32(d0, d2);

    float s0 = vaddvq_f32(a0);
    float s1 = vaddvq_f32(b0);
    float s2 = vaddvq_f32(c0);
    float s3 = vaddvq_f32(d0);

    for (; j < n; j++) {
        float xv = x[j];
        s0 += w0[j] * xv;
        s1 += w1[j] * xv;
        s2 += w2[j] * xv;
        s3 += w3[j] * xv;
    }
    out[0] = s0; out[1] = s1; out[2] = s2; out[3] = s3;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }
    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    /* round chunk to a multiple of 4 so all full chunks use dot4_neon */
    chunk = (chunk + 3) & ~3;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            for (; i + 3 < end; i += 4) {
                dot4_neon(w + (size_t)i * n, (size_t)n, x, n, xout + i);
            }
            for (; i < end; i++) {
                xout[i] = dot_neon(w + (size_t)i * n, x, n);
            }
        });
}

