    b0 = vaddq_f32(b0, b1); b2 = vaddq_f32(b2, b3); b0 = vaddq_f32(b0, b2);
    c0 = vaddq_f32(c0, c1); c2 = vaddq_f32(c2, c3); c0 = vaddq_f32(c0, c2);
    d0 = vaddq_f32(d0, d1); d2 = vaddq_f32(d2, d3); d0 = vaddq_f32(d0, d2);
