void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }

    const int d4 = d & ~3;          /* rows handled by 4-row kernel */
    const int blocks = d4 >> 2;     /* groups of 4 rows          */

    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > blocks) nchunk = blocks;
    int chunk = (blocks + nchunk - 1) / nchunk;
    if (chunk < 1) chunk = 1;
    nchunk = (blocks + chunk - 1) / chunk;

    const size_t stride = (size_t)n;
    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > blocks) end = blocks;
            for (int b = start; b < end; b++) {
                int i = b << 2;
                const float* r0 = w + (size_t)i       * stride;
                const float* r1 = w + (size_t)(i + 1) * stride;
                const float* r2 = w + (size_t)(i + 2) * stride;
                const float* r3 = w + (size_t)(i + 3) * stride;
                dot4_neon(r0, r1, r2, r3, x, n, xout + i);
            }
        });

    /* Tail rows (d not a multiple of 4). */
    for (int i = d4; i < d; i++)
        xout[i] = dot_neon(w + (size_t)i * n, x, n);
}

