static inline float hsum4(float32x4_t a0, float32x4_t a1,
                          float32x4_t a2, float32x4_t a3) {
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a0 = vaddq_f32(a0, a2);
    return vaddvq_f32(a0);
}

/* Single-row dot: same summation order as champion (4 accs, 16-wide). */
static inline float dot_neon_1(const float* __restrict w,
                               const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    float sum = hsum4(a0, a1, a2, a3);
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

/* Two-row dot: shares x vector loads across both rows.
   Each row's per-element accumulation order matches dot_neon_1 exactly. */
static inline void dot_neon_2(float* __restrict o0, float* __restrict o1,
                              const float* __restrict w0,
                              const float* __restrict w1,
                              const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    float32x4_t b0 = vdupq_n_f32(0.0f);
    float32x4_t b1 = vdupq_n_f32(0.0f);
    float32x4_t b2 = vdupq_n_f32(0.0f);
    float32x4_t b3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        float32x4_t x0 = vld1q_f32(x + j);
        float32x4_t x1 = vld1q_f32(x + j + 4);
        float32x4_t x2 = vld1q_f32(x + j + 8);
        float32x4_t x3 = vld1q_f32(x + j + 12);
        a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
        b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),      x0);
        a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4),  x1);
        b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(w0 + j + 8),  x2);
        b2 = vfmaq_f32(b2, vld1q_f32(w1 + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(w0 + j + 12), x3);
        b3 = vfmaq_f32(b3, vld1q_f32(w1 + j + 12), x3);
    }
    float s0 = hsum4(a0, a1, a2, a3);
    float s1 = hsum4(b0, b1, b2, b3);
    for (; j < n; j++) {
        s0 += w0[j] * x[j];
        s1 += w1[j] * x[j];
    }
    *o0 = s0;
    *o1 = s1;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon_1(w + (size_t)i * n, x, n);
        return;
    }
    /* ~4 chunks per core for load balance across 6P+6E cores. */
    const int TARGET_CHUNKS = 48;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    chunk = (chunk + 1) & ~1;           /* even chunk so pairs stay in-chunk */
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            for (; i + 1 < end; i += 2) {
                dot_neon_2(&xout[i], &xout[i + 1],
                           w + (size_t)i * n,
                           w + (size_t)(i + 1) * n,
                           x, n);
            }
            if (i < end) {
                xout[i] = dot_neon_1(w + (size_t)i * n, x, n);
            }
        });
}

