        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), x3);
