        float32x4_t x5 = vld1q_f32(x + j + 20);
        float32x4_t x6 = vld1q_f32(x + j + 24);
        float32x4_t x7 = vld1q_f32(x + j + 28);
        a0 = vfmaq_f32(a0, vld1q_f32(w + j + 16), x4);
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 20), x5);
