/* 8-accumulator NEON FMA dot product.
 * Uses MORE independent FMA chains to hide multiply latency, and issues a
 * software prefetch of the streaming W row so the L2 fetcher stays ahead.
 * The tail is handled by a 4-wide NEON pass (n is a multiple of 4 in all
 * real models) followed by a scalar cleanup for safety. */
static inline float dot_neon(const float* __restrict w,
                             const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    float32x4_t a4 = vdupq_n_f32(0.0f);
    float32x4_t a5 = vdupq_n_f32(0.0f);
    float32x4_t a6 = vdupq_n_f32(0.0f);
    float32x4_t a7 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 31 < n; j += 32) {
        __builtin_prefetch(w + j + 256, 0, 0);
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
        a4 = vfmaq_f32(a4, vld1q_f32(w + j + 16), vld1q_f32(x + j + 16));
        a5 = vfmaq_f32(a5, vld1q_f32(w + j + 20), vld1q_f32(x + j + 20));
        a6 = vfmaq_f32(a6, vld1q_f32(w + j + 24), vld1q_f32(x + j + 24));
        a7 = vfmaq_f32(a7, vld1q_f32(w + j + 28), vld1q_f32(x + j + 28));
    }
    /* Pairwise tree reduction (numerically well-behaved). */
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a4 = vaddq_f32(a4, a5);
    a6 = vaddq_f32(a6, a7);
    a0 = vaddq_f32(a0, a2);
    a4 = vaddq_f32(a4, a6);
    a0 = vaddq_f32(a0, a4);
    float sum = vaddvq_f32(a0);

    /* 4-wide tail; n is a multiple of 4 in practice so this usually eats it. */
    for (; j + 3 < n; j += 4) {
        float32x4_t p = vmulq_f32(vld1q_f32(w + j), vld1q_f32(x + j));
        sum += vaddvq_f32(p);
    }
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

