        c3 = vfmaq_f32(c3, vld1q_f32(w2 + j + 12), x3);
        d0 = vfmaq_f32(d0, vld1q_f32(w3 + j),      x0);
        d1 = vfmaq_f32(d1, vld1q_f32(w3 + j + 4),  x1);
        d2 = vfmaq_f32(d2, vld1q_f32(w3 + j + 8),  x2);
        d3 = vfmaq_f32(d3, vld1q_f32(w3 + j + 12), x3);
    }
    a0 = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    b0 = vaddq_f32(vaddq_f32(b0, b1), vaddq_f32(b2, b3));
    c0 = vaddq_f32(vaddq_f32(c0, c1), vaddq_f32(c2, c3));
    d0 = vaddq_f32(vaddq_f32(d0, d1), vaddq_f32(d2, d3));
    float s0 = vaddvq_f32(a0);
    float s1 = vaddvq_f32(b0);
    float s2 = vaddvq_f32(c0);
    float s3 = vaddvq_f32(d0);
    for (; j < n; j++) {
        float xv = x[j];
        s0 += w0[j] * xv;
        s1 += w1[j] * xv;
        s2 += w2[j] * xv;
        s3 += w3[j] * xv;
    }
    o[0] = s0; o[1] = s1; o[2] = s2; o[3] = s3;
}

static inline float dot1(const float* __restrict w,
                         const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    a0 = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    float sum = vaddvq_f32(a0);
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot1(w + (size_t)i * n, x, n);
        return;
    }
    /* Chunk rows; each chunk uses the 4-row kernel for x reuse. */
    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    chunk = (chunk + ROWS - 1) / ROWS * ROWS;   /* multiple of ROWS */
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            size_t stride = (size_t)n;
            for (; i + ROWS <= end; i += ROWS) {
                dot4(w + (size_t)i * stride,
                     w + (size_t)(i + 1) * stride,
                     w + (size_t)(i + 2) * stride,
                     w + (size_t)(i + 3) * stride,
                     x, n, xout + i);
            }
            for (; i < end; i++) {
                xout[i] = dot1(w + (size_t)i * stride, x, n);
            }
        });
}

