/* Single-row NEON dot: 4 independent accumulators, identical order to champion. */
static inline float dot_neon(const float* __restrict w,
                             const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(w + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(w + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(w + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(w + j + 12), vld1q_f32(x + j + 12));
    }
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a0 = vaddq_f32(a0, a2);
    float sum = vaddvq_f32(a0);
    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

/* Two rows at once: x vectors are loaded once and reused for both rows.
   Per-row accumulation order / tree is identical to dot_neon, so numerics match. */
static inline void dot2_neon(const float* __restrict w0,
                             const float* __restrict w1,
                             const float* __restrict x, int n,
                             float* __restrict out0,
                             float* __restrict out1) {
    float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
    float32x4_t b0 = vdupq_n_f32(0.0f), b1 = vdupq_n_f32(0.0f);
    float32x4_t b2 = vdupq_n_f32(0.0f), b3 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 15 < n; j += 16) {
        float32x4_t x0 = vld1q_f32(x + j);
        float32x4_t x1 = vld1q_f32(x + j + 4);
        float32x4_t x2 = vld1q_f32(x + j + 8);
        float32x4_t x3 = vld1q_f32(x + j + 12);
        a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
        a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(w0 + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(w0 + j + 12), x3);
        b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),      x0);
        b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4),  x1);
        b2 = vfmaq_f32(b2, vld1q_f32(w1 + j + 8),  x2);
        b3 = vfmaq_f32(b3, vld1q_f32(w1 + j + 12), x3);
    }
    a0 = vaddq_f32(a0, a1);
    a2 = vaddq_f32(a2, a3);
    a0 = vaddq_f32(a0, a2);
    b0 = vaddq_f32(b0, b1);
    b2 = vaddq_f32(b2, b3);
    b0 = vaddq_f32(b0, b2);
    float s0 = vaddvq_f32(a0);
    float s1 = vaddvq_f32(b0);
    for (; j < n; j++) {
        s0 += w0[j] * x[j];
        s1 += w1[j] * x[j];
    }
    *out0 = s0;
    *out1 = s1;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;

    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }

    /* ~2 chunks per core for load balancing; even chunk size so pair loop is clean. */
    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    chunk = (chunk + 1) & ~1;      /* round up to even */
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            for (; i + 1 < end; i += 2) {
                dot2_neon(w + (size_t)i * n,
                          w + (size_t)(i + 1) * n,
                          x, n,
                          xout + i, xout + i + 1);
            }
            if (i < end) {
                xout[i] = dot_neon(w + (size_t)i * n, x, n);
            }
        });
}

