    for (; j < n; j++) sum += w[j] * x[j];
    return sum;
}

/* Process 4 rows sharing the same x-chunk: one x load feeds 4 FMAs per row. */
static inline void dot4_neon(const float* __restrict w0,
                             const float* __restrict w1,
                             const float* __restrict w2,
                             const float* __restrict w3,
                             const float* __restrict x, int n,
                             float* __restrict o0, float* __restrict o1,
                             float* __restrict o2, float* __restrict o3) {
    float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
    float32x4_t b0 = vdupq_n_f32(0.0f), b1 = vdupq_n_f32(0.0f);
    float32x4_t b2 = vdupq_n_f32(0.0f), b3 = vdupq_n_f32(0.0f);
    float32x4_t c0 = vdupq_n_f32(0.0f), c1 = vdupq_n_f32(0.0f);
    float32x4_t c2 = vdupq_n_f32(0.0f), c3 = vdupq_n_f32(0.0f);
    float32x4_t d0 = vdupq_n_f32(0.0f), d1 = vdupq_n_f32(0.0f);
    float32x4_t d2 = vdupq_n_f32(0.0f), d3 = vdupq_n_f32(0.0f);

    int j = 0;
    for (; j + 15 < n; j += 16) {
        float32x4_t x0 = vld1q_f32(x + j);
        float32x4_t x1 = vld1q_f32(x + j + 4);
        float32x4_t x2 = vld1q_f32(x + j + 8);
        float32x4_t x3 = vld1q_f32(x + j + 12);

        a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
        a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(w0 + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(w0 + j + 12), x3);

        b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),      x0);
        b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4),  x1);
        b2 = vfmaq_f32(b2, vld1q_f32(w1 + j + 8),  x2);
        b3 = vfmaq_f32(b3, vld1q_f32(w1 + j + 12), x3);

        c0 = vfmaq_f32(c0, vld1q_f32(w2 + j),      x0);
        c1 = vfmaq_f32(c1, vld1q_f32(w2 + j + 4),  x1);
        c2 = vfmaq_f32(c2, vld1q_f32(w2 + j + 8),  x2);
        c3 = vfmaq_f32(c3, vld1q_f32(w2 + j + 12), x3);

        d0 = vfmaq_f32(d0, vld1q_f32(w3 + j),      x0);
        d1 = vfmaq_f32(d1, vld1q_f32(w3 + j + 4),  x1);
        d2 = vfmaq_f32(d2, vld1q_f32(w3 + j + 8),  x2);
        d3 = vfmaq_f32(d3, vld1q_f32(w3 + j + 12), x3);
    }

    a0 = vaddq_f32(a0, a1); a2 = vaddq_f32(a2, a3);
    float s0 = vaddvq_f32(vaddq_f32(a0, a2));
    b0 = vaddq_f32(b0, b1); b2 = vaddq_f32(b2, b3);
    float s1 = vaddvq_f32(vaddq_f32(b0, b2));
    c0 = vaddq_f32(c0, c1); c2 = vaddq_f32(c2, c3);
    float s2 = vaddvq_f32(vaddq_f32(c0, c2));
    d0 = vaddq_f32(d0, d1); d2 = vaddq_f32(d2, d3);
    float s3 = vaddvq_f32(vaddq_f32(d0, d2));

    for (; j < n; j++) {
        float xv = x[j];
        s0 += w0[j] * xv;
        s1 += w1[j] * xv;
        s2 += w2[j] * xv;
        s3 += w3[j] * xv;
    }
    *o0 = s0; *o1 = s1; *o2 = s2; *o3 = s3;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }

    const int TARGET_CHUNKS = 24;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            for (; i + 3 < end; i += 4) {
                dot4_neon(w + (size_t)i       * n,
                          w + (size_t)(i + 1) * n,
                          w + (size_t)(i + 2) * n,
                          w + (size_t)(i + 3) * n,
                          x, n,
                          &xout[i], &xout[i + 1],
                          &xout[i + 2], &xout[i + 3]);
            }
            for (; i < end; i++)
                xout[i] = dot_neon(w + (size_t)i * n, x, n);
        });
}

