/* Two rows sharing the same x loads; doubles ILP on FMA chains
   while preserving per-row accumulation order (bit-identical). */
static inline void dot2_neon(float* __restrict o0, float* __restrict o1,
                             const float* __restrict w0,
                             const float* __restrict w1,
                             const float* __restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t b0 = vdupq_n_f32(0.0f);
    float32x4_t b1 = vdupq_n_f32(0.0f);
    int j = 0;
    for (; j + 7 < n; j += 8) {
        __builtin_prefetch(w0 + j + 32);
        __builtin_prefetch(w1 + j + 32);
        float32x4_t xv0 = vld1q_f32(x + j);
        float32x4_t xv1 = vld1q_f32(x + j + 4);
        a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),     xv0);
        a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4), xv1);
        b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),     xv0);
        b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4), xv1);
    }
    a0 = vaddq_f32(a0, a1);
    b0 = vaddq_f32(b0, b1);
    float s0 = vaddvq_f32(a0);
    float s1 = vaddvq_f32(b0);
    for (; j < n; j++) {
        s0 += w0[j] * x[j];
        s1 += w1[j] * x[j];
    }
    *o0 = s0;
    *o1 = s1;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    if (d < 48) {
        for (int i = 0; i < d; i++)
            xout[i] = dot_neon(w + (size_t)i * n, x, n);
        return;
    }
    /* 4 chunks per P-core for good load-balance across 12 cores. */
    const int TARGET_CHUNKS = 48;
    int nchunk = TARGET_CHUNKS;
    if (nchunk > d) nchunk = d;
    int chunk = (d + nchunk - 1) / nchunk;
    if (chunk & 1) chunk++;              /* even so 2-row pairing works */
    nchunk = (d + chunk - 1) / chunk;

    dispatch_apply(nchunk,
        dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
        ^(size_t t) {
            int start = (int)t * chunk;
            int end   = start + chunk;
            if (end > d) end = d;
            int i = start;
            for (; i + 1 < end; i += 2) {
                dot2_neon(&xout[i], &xout[i + 1],
                          w + (size_t)i * n,
                          w + (size_t)(i + 1) * n,
                          x, n);
            }
            if (i < end) {
                xout[i] = dot_neon(w + (size_t)i * n, x, n);
            }
        });
}

